
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b97_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b97", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.548802515228184e+00, -3.481413526419393e+00, -3.387025357252935e+00, -3.256369121085899e+00, -3.078564623733676e+00, -2.842499618942815e+00, -2.540135237186485e+00, -2.172633354156862e+00, -1.758704557240800e+00, -1.335392271862119e+00, -9.145512064283280e-01, -6.141987215312484e-01, -5.312602821413703e-01, -4.373465026449267e-01, -3.166202905271644e-01, -1.998439355468531e-01, -1.170143868119336e-01, -5.079497288692644e-02, -1.196649971804887e-02, -1.391003682177599e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


